BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('HBSE-107-2-014','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第9條、第10條、第11條、第12條、第13條（長照服務提供方式，以及居家式含家事服務、社區式含交通接送、機構住宿式含緊急送醫、家庭照顧者支持服務含喘息服務），最後修正公布日：第9條 2015-06-03（制定公布）、第10條 2015-06-03（制定公布）、第11條 2015-06-03（制定公布）、第12條 2015-06-03（制定公布）、第13條 2015-06-03（制定公布），本題考試日 2018-07-28 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP104-2-39','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第9條（社區式服務含日間照顧、家庭托顧、團體家屋、小規模多機能等），最後修正公布日：第9條 2015-06-03（制定公布）（本法 2015-06-03 公布、2017-06-03 施行，考試時已公布），本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP105-1-04','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考長期照顧服務法第15條（基金來源）。考試時之條文（2015-06-03 公布、2017-06-03 施行）設置「長照服務發展基金」，來源為政府預算撥充、菸品健康福利捐、捐贈收入、基金孳息收入及其他收入；2017-01-26 修正改設「特種基金」，並增列遺產稅及贈與稅、菸酒稅菸品調增稅率所增加之稅課收入，公益彩券盈餘於修正前後均非基金來源，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP105-2-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第13條（家庭照顧者支持服務項目），最後修正公布日：第13條 2015-06-03（制定公布）（本法 2015-06-03 公布、2017-06-03 施行，考試時已公布），本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP106-2-01','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第40條（長照服務品質基準之五項原則），最後修正公布日：第40條 2015-06-03（制定公布），本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP106-2-16','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考老人福利法第41條（老人保護及安置費用）及長期照顧服務法第15條（特種基金）、第35條（收費參考資訊及收費項目報主管機關核定）、第36條（收據及不得超額或擅立項目收費）。長期照顧服務法各條考試日後未再修正；老人福利法第41條於 2020-05-27 修正，增列配偶、刪除「短期」，並改為以書面行政處分通知於六十日內返還、得減輕或免除，但保護及安置費用仍由主管機關先行支付後通知義務人返還，並非由主管機關負擔，選項(A)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP106-2-18','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第3條（長照服務體系之定義），最後修正公布日：第3條 2015-06-03（制定公布），本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP106-2-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第3條（長期照顧指身心失能持續已達或預期達六個月以上者），最後修正公布日：第3條 2015-06-03（制定公布），本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP107-1-10','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考長期照顧服務法第1條（長照服務之提供不得因國籍等有差別待遇）、第14條（資源調查應考慮多元文化特色）、第21條（長照機構分類）及第40條（品質基準以服務使用者為中心）。第1條、第21條、第40條考試日後未再修正；第14條於 2019-06-19 修正，僅將原住民族地區長照規劃之「會商原住民族委員會」改為「會同中央原住民族主管機關」，應考慮多元文化特色之規定未變，選項(C)仍為與法令規定不合者。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP107-2-15','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考長期照顧服務法第3條（長期照顧之定義）、第9條（團體家屋屬社區式）、第15條（特種基金來源含遺產稅及贈與稅稅率調增所增加之稅課收入）及第62條（本法施行前已提供長照服務者）。第3條、第9條、第15條考試日後未再修正；第62條於 2021-06-09 修正，增訂實際執行長照服務人員之認證、繼續教育、登錄及處罰適用本法之但書，本法施行前已提供長照服務者仍得依原適用法令繼續提供（「施行後五年內取得或換發設立許可」之規定已於考試前之 2017-01-26 修正刪除），選項(D)仍錯誤，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP108-1-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第3條（長期照顧及身心失能者之定義），最後修正公布日：第3條 2015-06-03（制定公布），本題考試日 2019-01-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP108-1-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務機構法人條例第3條（長照機構法人指提供機構住宿式服務之法人），最後修正公布日：第3條 2018-01-31（制定公布），本題考試日 2019-01-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070051'),('SP108-2-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第1條（立法目的），最後修正公布日：第1條 2015-06-03（制定公布），本題考試日 2019-07-27 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP109-1-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第9條、第10條（社區式服務之內容；到宅提供者屬居家式），最後修正公布日：第9條 2015-06-03（制定公布）、第10條 2015-06-03（制定公布），本題考試日 2020-02-15 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP109-1-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務機構法人條例第6條、第8條、第11條、第16條（得設立社會福利機構、應有必要之財產、董事會每半年至少開會一次、不得投資衍生性金融商品），最後修正公布日：第6條 2018-01-31（制定公布）、第8條 2018-01-31（制定公布）、第11條 2018-01-31（制定公布）、第16條 2018-01-31（制定公布），本題考試日 2020-02-15 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070051'),('SP109-2-39','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第13條（家庭照顧者支持服務含喘息服務），最後修正公布日：第13條 2015-06-03（制定公布），本題考試日 2020-08-01 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP109-2-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第9條（社區式服務含日間照顧、家庭托顧、臨時住宿、團體家屋、小規模多機能等），最後修正公布日：第9條 2015-06-03（制定公布），本題考試日 2020-08-01 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP110-1-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第15條（長照特種基金之來源），最後修正公布日：第15條 2017-01-26，本題考試日 2021-02-06 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP110-2-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第34條（機構住宿式長照機構應投保公共意外責任險），最後修正公布日：第34條 2019-06-19，本題考試日 2021-08-21 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SP111-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務機構法人條例第14條（財產總額或年度收入總額達新臺幣三千萬元以上者財務報告應經會計師查核簽證，並應主動公開），最後修正公布日：第14條 2018-01-31（制定公布），本題考試日 2022-02-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070051'),('SW-104-1-06','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧十年計畫（政策）之服務對象（長期照顧服務法於考試日後之 2015-06-03 始公布），非長期照顧服務法條文內容，不受日後條文修正影響，官方答案仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SW-104-2-39','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第21條、第35條、第36條、第40條（長照機構依服務內容分五類、收費規定及品質基準考量多元文化；選項(B)為民國104年6月公布本法之沿革），最後修正公布日：第21條 2015-06-03（制定公布）、第35條 2015-06-03（制定公布）、第36條 2015-06-03（制定公布）、第40條 2015-06-03（制定公布）（本法 2015-06-03 公布、2017-06-03 施行，考試時已公布），本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040'),('SW-105-2-08','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考長期照顧服務法第13條（家庭照顧者支持服務項目），最後修正公布日：第13條 2015-06-03（制定公布）（本法 2015-06-03 公布、2017-06-03 施行，考試時已公布），本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070040');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>23 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>23 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'fa9e621e0a893a95f8143bcc6d20eb6b' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_23, count(*) FILTER (WHERE q.legal_status='changed') changed_0, count(*) total_23 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
